                release_state?: "NOT_ACQUIRED" | "UNCONFIRMED" | "SHUTDOWN";
                artifacts_verified?: boolean;
                /** @enum {unknown} */
                device_health?: "NOT_PROBED" | "HEALTHY" | "UNHEALTHY";
